  api("POST", "/project/participant", {
    project: { id: projectId },
    employee: { id: emp1Id },
    adminAccess: true,
  }),
  api("POST", "/project/participant", {
    project: { id: projectId },
    employee: { id: emp2Id },
    adminAccess: false,
  }),
]);

const activityId = paRes.value.activity.id;

// Build timesheet entries — UTC-safe date arithmetic
